1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type ClaimStep = {
19	  op: "claim";
20	  policy: number;
21	  incident: {
22	    cause: string;
23	    damages: Damage[];
24	  };
25	};
26	
27	export type Step = QuoteStep | ClaimStep;
28	
29	export type Customer = {
30	  yearsWithMHPCO: number;
31	};
32	
33	export type Scenario = {
34	  customer: Customer;
35	  steps: Step[];
36	};
37	
38	export type ScenarioResults = {
39	  results: unknown[];
40	};
41	
42	const sum = (amounts: number[]): number =>
43	  amounts.reduce((total, amount) => total + amount, 0);
44	
45	const PROCESSING_FEE = 5;
46	
47	// Binary floating point makes exact multiples land a hair off (100 * 1.1 + 5 =
48	// 115.00000000000001); snap to cent precision so only genuine fractions round.
49	const atCentPrecision = (amount: number): number => Number(amount.toFixed(6));
50	
51	// The office rounds every amount its own way: premiums it collects go up,
52	// payouts it hands out go down.
53	const roundUpInMHPCOsFavour = (amount: number): number =>
54	  Math.ceil(atCentPrecision(amount));
55	
56	const roundDownInMHPCOsFavour = (amount: number): number =>
57	  Math.floor(atCentPrecision(amount));
58	
59	// One entry per insurable type: every fact the office knows about a type lives
60	// here, so adding a type is a single edit.
61	type ItemKind = {
62	  basePremium: number;
63	  insuranceValue: number;
64	  isComponent: boolean;
65	};
66	
67	const ITEM_CATALOGUE: Record<string, ItemKind> = {
68	  sword: { basePremium: 100, insuranceValue: 1000, isComponent: false },
69	  amulet: { basePremium: 60, insuranceValue: 600, isComponent: false },
70	  staff: { basePremium: 80, insuranceValue: 800, isComponent: false },
71	  potion: { basePremium: 40, insuranceValue: 400, isComponent: false },
72	  rune: { basePremium: 25, insuranceValue: 250, isComponent: true },
73	  moonstone: { basePremium: 25, insuranceValue: 250, isComponent: true },
74	};
75	
76	const kindOf = (item: Item): ItemKind => ITEM_CATALOGUE[item.type];
77	
78	const basePremiumOf = (item: Item): number => kindOf(item).basePremium;
79	
80	const BLOCK_SIZE = 3;
81	const BLOCK_BASE_PREMIUM = 60;
82	
83	const groupByType = (items: Item[]): Item[][] => {
84	  const itemsByType = new Map<string, Item[]>();
85	
86	  for (const item of items) {
87	    const sameTypeItems = itemsByType.get(item.type);
88	    if (sameTypeItems) sameTypeItems.push(item);
89	    else itemsByType.set(item.type, [item]);
90	  }
91	
92	  return [...itemsByType.values()];
93	};
94	
95	const isComponent = (item: Item): boolean => kindOf(item).isComponent;
96	
97	// A block is a special price for exactly 3 alike components; any other count,
98	// and any main item, is charged per item.
99	const sameTypeBasePremiumOf = (sameTypeItems: Item[]): number =>
100	  sameTypeItems.length === BLOCK_SIZE && isComponent(sameTypeItems[0])
101	    ? BLOCK_BASE_PREMIUM
102	    : sum(sameTypeItems.map(basePremiumOf));
103	
104	const policyBasePremiumOf = (items: Item[]): number =>
105	  sum(groupByType(items).map(sameTypeBasePremiumOf));
106	
107	// Both rate tables stack the same way: every rule whose condition holds
108	// contributes its signed rate, and the rates add. Discounts carry a negative
109	// rate so a table sums without sign-juggling at the call site.
110	type RateRule<Subject> = {
111	  appliesTo: (subject: Subject) => boolean;
112	  rate: number;
113	};
114	
115	const totalRateOf = <Subject>(
116	  rules: RateRule<Subject>[],
117	  subject: Subject,
118	): number =>
119	  sum(
120	    rules.filter(({ appliesTo }) => appliesTo(subject)).map(({ rate }) => rate),
121	  );
122	
123	const HIGH_ENCHANTMENT_THRESHOLD = 5;
124	
125	const isCursed = (item: Item): boolean => item.cursed === true;
126	
127	const isHighlyEnchanted = (item: Item): boolean =>
128	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
129	
130	const ITEM_SURCHARGES: RateRule<Item>[] = [
131	  { appliesTo: isCursed, rate: 0.5 },
132	  { appliesTo: isHighlyEnchanted, rate: 0.3 },
133	];
134	
135	const itemSurchargeRateOf = (item: Item): number =>
136	  totalRateOf(ITEM_SURCHARGES, item);
137	
138	// Item-specific surcharges are charged on that item's own base premium, not on
139	// the policy total.
140	const itemSurchargesOf = (item: Item): number =>
141	  basePremiumOf(item) * itemSurchargeRateOf(item);
142	
143	// Everything outside the item list that a policy-wide modifier may depend on:
144	// who is asking, and where this quote sits in their history with the office.
145	type QuoteContext = {
146	  customer: Customer;
147	  precedingQuotes: number;
148	};
149	
150	const LOYALTY_YEARS_THRESHOLD = 2;
151	
152	const isLoyal = ({ customer }: QuoteContext): boolean =>
153	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
154	
155	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
156	  precedingQuotes > 0;
157	
158	const alwaysApplies = (): boolean => true;
159	
160	const POLICY_MODIFIERS: RateRule<QuoteContext>[] = [
161	  { appliesTo: alwaysApplies, rate: 0.1 }, // first insurance surcharge
162	  { appliesTo: isLoyal, rate: -0.2 },
163	  { appliesTo: isFollowUpContract, rate: -0.15 },
164	];
165	
166	// Policy-wide modifiers are charged on the base premium alone, never on base +
167	// item surcharges: a cursed sword quotes at 100 + 50 + 10 + 5 = 165, where the
168	// 10 is 10 % of 100 rather than of 150.
169	const policyModifierRateOf = (context: QuoteContext): number =>
170	  totalRateOf(POLICY_MODIFIERS, context);
171	
172	const quote = (step: QuoteStep, context: QuoteContext): number => {
173	  const policyBasePremium = policyBasePremiumOf(step.items);
174	  const itemSurcharges = sum(step.items.map(itemSurchargesOf));
175	  const policyModifiers = policyBasePremium * policyModifierRateOf(context);
176	
177	  return roundUpInMHPCOsFavour(
178	    policyBasePremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
179	  );
180	};
181	
182	const DEDUCTIBLE_PER_DAMAGE = 100;
183	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
184	
185	const insuranceSumOf = (items: Item[]): number =>
186	  sum(items.map((item) => kindOf(item).insuranceValue));
187	
188	const REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
189	const REDUCED_REIMBURSEMENT_SHARE = 0.5;
190	
191	// Heavily enchanted items are notoriously hard to appraise, so the office only
192	// reimburses half of the damage before applying the deductible.
193	const reimbursementShareOf = (item: Item): number =>
194	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
195	    ? REDUCED_REIMBURSEMENT_SHARE
196	    : 1;
197	
198	const payoutForDamage = (damage: Damage, damagedItem: Item): number =>
199	  damage.amount * reimbursementShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
200	
201	// A claim points at the quote step that issued its policy. Every scenario under
202	// test points at a real quote; rejecting a dangling or non-quote reference is a
203	// deferred validation test, so this narrows without complaining for now.
204	const policyOf = (scenario: Scenario, step: ClaimStep): QuoteStep =>
205	  scenario.steps[step.policy] as QuoteStep;
206	
207	const claim = (step: ClaimStep, policy: QuoteStep) => {
208	  const cap = insuranceSumOf(policy.items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
209	  const payout = roundDownInMHPCOsFavour(
210	    sum(
211	      step.incident.damages.map((damage) =>
212	        payoutForDamage(
213	          damage,
214	          policy.items.find((item) => item.type === damage.itemType) as Item,
215	        ),
216	      ),
217	    ),
218	  );
219	
220	  return { payout, remainingCap: cap - payout };
221	};
222	
223	export const runScenario = (scenario: Scenario): ScenarioResults => {
224	  return {
225	    results: scenario.steps.map((step, precedingSteps) => {
226	      if (step.op === "claim") {
227	        return claim(step, policyOf(scenario, step));
228	      }
229	
230	      return {
231	        // Steps, not quotes: with only quote-then-claim scenarios under test the
232	        // two counts agree. A claim before a quote would make them diverge, and
233	        // that is the deferred test's job to pin down.
234	        premium: quote(step, {
235	          customer: scenario.customer,
236	          precedingQuotes: precedingSteps,
237	        }),
238	      };
239	    }),
240	  };
241	};
