// A damage names the type it hit; the clauses that shape its payout live on the
// insured item itself. Every scenario under test damages a covered type;
// rejecting a damage the policy does not cover is a deferred validation test,
// so this narrows without complaining for now.
const damagedItemOf = (policy: QuoteStep, damage: Damage): Item =>
  policy.items.find((item) => item.type === damage.itemType) as Item;

const claim = (step: ClaimStep, policy: QuoteStep) => {
  const cap = insuranceSumOf(policy.items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
  const payout = roundDownInMHPCOsFavour(
    sum(
      step.incident.damages.map((damage) =>
        payoutForDamage(damage, damagedItemOf(policy, damage)),
      ),
    ),
  );

  return { payout, remainingCap: cap - payout };
};
